schema:
CREATE TABLE ACTORDIRECTOR (
    TIMESTAMP INT,
    ACTOR_ID INT,
    DIRECTOR_ID INT,
    PRIMARY KEY (TIMESTAMP)
);

counterexample:
-- Under the schema with TIMESTAMP as primary key, all INSERTs must have unique TIMESTAMPs.
-- For example, inserting data where a group (ACTOR_ID=1, DIRECTOR_ID=1) has 3 rows with unique TIMESTAMPs:
INSERT INTO ACTORDIRECTOR VALUES (1, 1, 1);
INSERT INTO ACTORDIRECTOR VALUES (2, 1, 1);
INSERT INTO ACTORDIRECTOR VALUES (3, 1, 1);
-- For this group, both Q1 and Q2 will return (1,1) because COUNT(*) = 3 and COUNT(DISTINCT TIMESTAMP) = 3.
-- To create a difference, we would need duplicate TIMESTAMPs, e.g., for group (ACTOR_ID=2, DIRECTOR_ID=2):
-- INSERT INTO ACTORDIRECTOR VALUES (4, 2, 2);
-- INSERT INTO ACTORDIRECTOR VALUES (4, 2, 2); -- This violates the primary key constraint and cannot be executed.
-- Thus, no valid INSERTs under the given schema can make Q1 and Q2 output different results.

